#!/usr/bin/env perl
# Run by tools/gen_openssl.sh inside a configured OpenSSL build directory:
#   perl -I. -Mconfigdata gen_openssl.pl <source-root> <sources.zig> <generated-list>
# Writes the compile groups of the static libcrypto and libssl as a Zig file, and the list of
# generated files (relative to the build directory) the build needs checked in.
use strict;
use warnings;
use File::Spec;
use File::Basename;
use Cwd qw(abs_path);

our (%unified_info, %config);
my ($srcroot, $zig_out, $list_out) = @ARGV;
$srcroot = abs_path($srcroot);

# Source paths in configdata are relative to the build directory; return them relative to the
# source root when they live there.
sub rel {
    my ($p) = @_;
    return $p if exists $unified_info{generate}{$p};
    my $abs = abs_path(File::Spec->rel2abs($p)) // File::Spec->rel2abs($p);
    return substr($abs, length($srcroot) + 1) if index($abs, "$srcroot/") == 0;
    die "path outside the source tree: $p\n";
}

my @groups = (
    [ crypto  => 'libcrypto' ],
    [ ssl     => 'libssl' ],
    [ default => 'providers/libdefault.a' ],
    [ common  => 'providers/libcommon.a' ],
);

my %generated;
my @out;
push @out, "//! Generated by tools/gen_openssl.sh; do not edit.\n";
push @out, "const Group = \@import(\"../group.zig\").Group;\n\n";

for my $g (@groups) {
    my ($name, $lib) = @$g;
    my (%inc, @c, @gen_c, @asm);
    for my $o (@{ $unified_info{sources}{$lib} }) {
        next if $o =~ /\.a$/;    # nested archives are groups of their own
        my @s = @{ $unified_info{sources}{$o} };
        die "object $o has several sources\n" unless @s == 1;
        my $leaf = $s[0];
        die "object $o is not compiled from a source: $leaf\n" if $leaf =~ /\.o$/;
        my $path = rel($leaf);
        $generated{$path} = 1 if exists $unified_info{generate}{$leaf};
        if ($leaf =~ /\.[sS]$/) { push @asm, $path }
        elsif (exists $unified_info{generate}{$leaf}) { push @gen_c, $path }
        else { push @c, $path }
        for my $i (@{ $unified_info{includes}{$o} || [] }) {
            my $r = $i eq '.' ? '.' : (File::Spec->file_name_is_absolute($i) || $i =~ m{^\.\./} ? undef : $i);
            $inc{$r} = 1 if defined $r;
        }
    }
    for my $i (@{ $unified_info{includes}{$lib} || [] }) {
        $inc{$i} = 1 unless File::Spec->file_name_is_absolute($i) || $i =~ m{^\.\./};
    }
    my @defs = @{ $unified_info{defines}{$lib} || [] };
    push @out, "pub const $name: Group = .{\n";
    push @out, "    .defines = &.{" . join(", ", map {"\"$_\""} sort @defs) . "},\n";
    push @out, "    .includes = &.{" . join(", ", map {"\"$_\""} sort keys %inc) . "},\n";
    push @out, "    .c = &.{\n" . join("", map {"        \"$_\",\n"} sort @c) . "    },\n";
    push @out, "    .gen_c = &.{\n" . join("", map {"        \"$_\",\n"} sort @gen_c) . "    },\n";
    push @out, "    .asm_files = &.{\n" . join("", map {"        \"$_\",\n"} sort @asm) . "    },\n";
    push @out, "};\n\n";
}

# Generated headers are not all produced by `make build_generated`; take every one of the library trees.
for my $p (keys %{ $unified_info{generate} }) {
    $generated{$p} = 1 if $p =~ m{^(?:include|crypto|providers|ssl)/.*\.(?:h|inc)$};
}

open(my $fh, '>', $zig_out) or die $!;
print $fh @out;
close $fh;

open($fh, '>', $list_out) or die $!;
print $fh "$_\n" for sort keys %generated;
close $fh;
